class Solution:
    def countSpecialNumbers(self, n: int) -> int:
        s = str(n)
        L = len(s)
        def P(m, k):
            r = 1
            for i in range(k):
                r *= m - i
            return r
        ans = sum(9 * P(9, d - 1) for d in range(1, L))
        used = set()
        for i, ch in enumerate(s):
            lo = 1 if i == 0 else 0
            cnt = sum(1 for x in range(lo, int(ch)) if x not in used)
            ans += cnt * P(10 - len(used) - 1, L - i - 1)
            if int(ch) in used:
                break
            used.add(int(ch))
        else:
            ans += 1
        return ans

