class Solution {
    private long P(long m, long k) {
        long r = 1;
        for (long i = 0; i < k; i++) r *= m - i;
        return r;
    }
    public int countSpecialNumbers(int n) {
        String s = Integer.toString(n);
        int L = s.length();
        long ans = 0;
        for (int d = 1; d < L; d++) ans += 9 * P(9, d - 1);
        boolean[] used = new boolean[10];
        int u = 0;
        for (int i = 0; i < L; i++) {
            int lo = (i == 0) ? 1 : 0, cnt = 0;
            for (int x = lo; x < s.charAt(i) - '0'; x++) if (!used[x]) cnt++;
            ans += cnt * P(10 - u - 1, L - i - 1);
            int d = s.charAt(i) - '0';
            if (used[d]) break;
            used[d] = true; u++;
            if (i == L - 1) ans++;
        }
        return (int) ans;
    }
}

