var countSpecialNumbers = function(n) {
    const s = String(n), L = s.length;
    const P = (m, k) => { let r = 1; for (let i = 0; i < k; i++) r *= m - i; return r; };
    let ans = 0;
    for (let d = 1; d < L; d++) ans += 9 * P(9, d - 1);
    const used = Array(10).fill(false);
    let u = 0, broke = false;
    for (let i = 0; i < L; i++) {
        const lo = i === 0 ? 1 : 0;
        let cnt = 0;
        for (let x = lo; x < +s[i]; x++) if (!used[x]) cnt++;
        ans += cnt * P(10 - u - 1, L - i - 1);
        const d = +s[i];
        if (used[d]) { broke = true; break; }
        used[d] = true; u++;
    }
    if (!broke) ans++;
    return ans;
};
